-- Risk kütüphanesi: Eksantrik pres (8), Hidrolik pres üretim (5), Abkant pres (5) — 01.11.2026.
-- phpMyAdmin > mehse veritabanı > SQL. Tekrar çalıştırılabilir (var olan klasör/madde atlanır).
SET NAMES utf8mb4;

INSERT INTO `tehlike_kategorileri` (`ad`, `anahtar`, `yontem`, `sira`, `created_at`, `updated_at`)
SELECT 'Ekipman – Eksantrik pres', 'ekipman_eksantrik_pres', NULL, 500, NOW(), NOW() FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM `tehlike_kategorileri` WHERE `anahtar` = 'ekipman_eksantrik_pres');

INSERT INTO `tehlikeler` (`tehlike_kategorisi_id`, `kod`, `bolum`, `faaliyet`, `tehlike`, `risk`, `mevcut_onlem`, `oneri`, `mevzuat`, `olasilik`, `frekans`, `siddet`, `son_olasilik`, `son_frekans`, `son_siddet`, `sorumlu`, `termin`, `matris`, `created_at`, `updated_at`)
SELECT (SELECT `id` FROM `tehlike_kategorileri` WHERE `anahtar` = 'ekipman_eksantrik_pres' LIMIT 1), 'EKP-001', 'Eksantrik Pres', 'Pres operasyonu', 'Işık bariyeri (AOPD) emniyet mesafesinin yetersiz olması ve fonksiyon testinin yapılmaması', 'Kök neden: Işık perdesi, koç durma süresi ölçülmeden koç bölgesine çok yakın monte edilmiş; vardiya başı test çubuğu ile fonksiyon kontrolü yapılmıyor. Operatör eli perdeyi geçip koç durmadan kalıp bölgesine ulaşabilir → parmak/el ezilmesi, uzuv kaybı.', 'Işık bariyeri mevcut; montaj mesafesi ve durma süresi ölçüm kaydı yok, günlük test formu tutulmuyor.', 'Koç durma süresi (T) ölçülmeli ve emniyet mesafesi EN ISO 13855’e göre hesaplanmalı: S = K × T + C (K = 2000 mm/s; S > 500 mm çıkarsa K = 1600 mm/s ile yeniden hesap; C = 8 × (d − 14) mm, d: bariyer çözünürlüğü). Bariyer hesaplanan mesafeye taşınmalı, kenarlardan ve üstten erişim sabit koruyucuyla kapatılmalı. Vardiya başı test çubuğuyla fonksiyon testi yapılıp forma işlenmeli; bariyer devre dışı bırakılamayacak (anahtarlı/şifreli) olmalı.', 'Makine Emniyeti Yönetmeliği (2006/42/AT) Ek-I; İş Ekipmanlarının Kullanımında Sağlık ve Güvenlik Şartları Yönetmeliği; TS EN ISO 16092-1, TS EN ISO 16092-2; TS EN ISO 13855; TS EN 61496', 6, 6, 40, 0.2, 6, 40, 'Bakım Şefi / Üretim Sorumlusu', 'Derhal — vardiya başı test sürekli', '{\"olasilik\":4,\"siddet\":5,\"son_olasilik\":1,\"son_siddet\":5}', NOW(), NOW() FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM `tehlikeler` WHERE `kod` = 'EKP-001');

INSERT INTO `tehlikeler` (`tehlike_kategorisi_id`, `kod`, `bolum`, `faaliyet`, `tehlike`, `risk`, `mevcut_onlem`, `oneri`, `mevzuat`, `olasilik`, `frekans`, `siddet`, `son_olasilik`, `son_frekans`, `son_siddet`, `sorumlu`, `termin`, `matris`, `created_at`, `updated_at`)
SELECT (SELECT `id` FROM `tehlike_kategorileri` WHERE `anahtar` = 'ekipman_eksantrik_pres' LIMIT 1), 'EKP-002', 'Eksantrik Pres', 'Pres operasyonu', 'Çift el kumandasında 0,5 saniye eşzamanlılık şartının sağlanmaması ve koruyucu yakanın uygunsuz olması', 'Kök neden: Butonlardan biri bantlanmış/sabitlenmiş ya da yakası olmayan butonlar dirsek veya tek elle basılabiliyor; eşzamanlılık (0,5 s) denetimi olmayan röle devresi. Operatör tek eliyle kalıp bölgesindeyken koç inebilir → el ezilmesi.', 'Çift el kumandası mevcut; butonlar yakasız, eşzamanlılık ve bırakınca durma testi yapılmıyor.', 'EN ISO 13851’e uygun (en az Tip IIIC) çift el kumanda ünitesi kullanılmalı: iki butona 0,5 s içinde basılmadıkça çevrim başlamamalı, butonlardan biri bırakılınca koç durmalı. Butonlar koruyucu yakalı ve birbirinden yeterli mesafede olmalı (tek elle/dirsekle basılamamalı); ünite EN ISO 13855’e göre hesaplanan mesafeye konmalı. Butonların köprülenmesi disiplin konusu yapılmalı, vardiya başı test edilmeli.', 'Makine Emniyeti Yönetmeliği (2006/42/AT) Ek-I; İş Ekipmanlarının Kullanımında Sağlık ve Güvenlik Şartları Yönetmeliği (kumanda sistemleri); TS EN ISO 13851; TS EN ISO 13855; TS EN ISO 16092-2', 3, 6, 40, 0.2, 6, 40, 'Bakım Şefi / Operatör', 'Derhal', '{\"olasilik\":3,\"siddet\":5,\"son_olasilik\":1,\"son_siddet\":5}', NOW(), NOW() FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM `tehlikeler` WHERE `kod` = 'EKP-002');

INSERT INTO `tehlikeler` (`tehlike_kategorisi_id`, `kod`, `bolum`, `faaliyet`, `tehlike`, `risk`, `mevcut_onlem`, `oneri`, `mevzuat`, `olasilik`, `frekans`, `siddet`, `son_olasilik`, `son_frekans`, `son_siddet`, `sorumlu`, `termin`, `matris`, `created_at`, `updated_at`)
SELECT (SELECT `id` FROM `tehlike_kategorileri` WHERE `anahtar` = 'ekipman_eksantrik_pres' LIMIT 1), 'EKP-003', 'Eksantrik Pres', 'Pres operasyonu / bakım', 'Volan, kayış-kasnak açık mekanizması ve kamalı (mekanik) kavramada çift vuruş (istem dışı tekrar) riski', 'Kök neden: Volan ve kayış-kasnak koruyucusu sökülmüş; eski tip kamalı kavramada kama/yay aşınması nedeniyle koç tek çevrim yerine ikinci kez iniyor. Kayışa kapılma, volan çarpması ve beklenmedik ikinci vuruşla el ezilmesi.', 'Volan koruyucusu kısmen var; kavrama ve kama düzeneği periyodik bakım planında yok.', 'Volan, kayış-kasnak ve dişliler EN ISO 14120’ye uygun sabit (alet olmadan sökülemeyen) koruyucularla tamamen kapatılmalı. Kamalı kavramalı preslerde kama, yay ve kavrama düzeneği üretici talimatına göre bakımdan geçirilmeli; mümkünse pnömatik kavrama-fren grubuna ve tekrar (çift vuruş) önleyici emniyet devresine dönüştürülmeli. Tek vuruş modu dışında çalışma yalnız uygun koruyucularla yapılmalı.', 'İş Ekipmanlarının Kullanımında Sağlık ve Güvenlik Şartları Yönetmeliği (hareketli parçalar, koruyucular); Makine Emniyeti Yönetmeliği (2006/42/AT) Ek-I; TS EN ISO 14120; TS EN ISO 16092-2', 3, 6, 40, 0.2, 6, 40, 'Bakım Şefi', '1 ay', '{\"olasilik\":3,\"siddet\":5,\"son_olasilik\":1,\"son_siddet\":5}', NOW(), NOW() FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM `tehlikeler` WHERE `kod` = 'EKP-003');

INSERT INTO `tehlikeler` (`tehlike_kategorisi_id`, `kod`, `bolum`, `faaliyet`, `tehlike`, `risk`, `mevcut_onlem`, `oneri`, `mevzuat`, `olasilik`, `frekans`, `siddet`, `son_olasilik`, `son_frekans`, `son_siddet`, `sorumlu`, `termin`, `matris`, `created_at`, `updated_at`)
SELECT (SELECT `id` FROM `tehlike_kategorileri` WHERE `anahtar` = 'ekipman_eksantrik_pres' LIMIT 1), 'EKP-004', 'Eksantrik Pres', 'Kalıp değişimi / bakım-onarım', 'Kalıp değişimi ve bakımda LOTO (kilitleme / etiketleme) uygulanmaması', 'Kök neden: Kalıp değişimi ve arıza müdahalesinde yalnız kumanda butonundan durdurma yapılıyor; ana şalter kilitlenmiyor, basınçlı hava boşaltılmıyor, volan durması beklenmiyor. Başka bir çalışanın presi çalıştırması veya artık enerjiyle koçun inmesi → ezilme, ölüm.', 'Yazılı LOTO talimatı, kişisel asma kilit ve etiket yok.', 'Prese özel yazılı LOTO talimatı hazırlanmalı: durdur → ana şalteri kapat ve kişisel asma kilitle kilitle → etiket as → pnömatik/hidrolik artık enerjiyi boşalt → volanın tam durmasını bekle → çalıştırmayı deneyerek enerjisizliği doğrula. Her bakımcıya kişisel kilit ve etiket verilmeli, çoklu kilitleme aparatı kullanılmalı; talimat presin üzerine asılmalı ve eğitim kayıt altına alınmalı.', 'İş Ekipmanlarının Kullanımında Sağlık ve Güvenlik Şartları Yönetmeliği (bakım işlemleri, enerji kaynaklarından ayırma); Güvenlik ve Sağlık İşaretleri Yönetmeliği; 6331 sayılı İş Sağlığı ve Güvenliği Kanunu', 3, 3, 40, 0.5, 3, 40, 'Bakım Şefi / İSG Uzmanı', '1 hafta — sürekli uygulama', '{\"olasilik\":3,\"siddet\":5,\"son_olasilik\":1,\"son_siddet\":5}', NOW(), NOW() FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM `tehlikeler` WHERE `kod` = 'EKP-004');

INSERT INTO `tehlikeler` (`tehlike_kategorisi_id`, `kod`, `bolum`, `faaliyet`, `tehlike`, `risk`, `mevcut_onlem`, `oneri`, `mevzuat`, `olasilik`, `frekans`, `siddet`, `son_olasilik`, `son_frekans`, `son_siddet`, `sorumlu`, `termin`, `matris`, `created_at`, `updated_at`)
SELECT (SELECT `id` FROM `tehlike_kategorileri` WHERE `anahtar` = 'ekipman_eksantrik_pres' LIMIT 1), 'EKP-005', 'Eksantrik Pres', 'Kalıp değişimi / ayar', 'Koç emniyet takozunun (mekanik blokaj çubuğu) kullanılmaması', 'Kök neden: Kalıp ayarı ve değişiminde koç yalnız fren/hidrolik ile tutuluyor; emniyet takozu yok ya da takoz takılıyken presin çalışmasını engelleyen kilitleme bulunmuyor. Fren kaçırması veya yanlışlıkla çalıştırmada koç düşer → ezilme, ölüm.', 'Emniyet takozu yok / kullanılmıyor.', 'Koç ile tabla arasına yükü taşıyacak kapasitede emniyet takozu (blokaj çubuğu) temin edilmeli; takoz yuvasından alındığında pres ana kumandasını kesen elektrik kilitlemeli emniyet svici (EN ISO 14119) ile takoz takılıyken presin çalışması engellenmeli. Kalıp altında yapılan her işte takoz kullanımı LOTO talimatına eklenmeli.', 'İş Ekipmanlarının Kullanımında Sağlık ve Güvenlik Şartları Yönetmeliği; Makine Emniyeti Yönetmeliği (2006/42/AT) Ek-I; TS EN ISO 16092-1; TS EN ISO 14119', 3, 3, 40, 0.2, 3, 40, 'Bakım Şefi', '1 ay', '{\"olasilik\":3,\"siddet\":5,\"son_olasilik\":1,\"son_siddet\":5}', NOW(), NOW() FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM `tehlikeler` WHERE `kod` = 'EKP-005');

INSERT INTO `tehlikeler` (`tehlike_kategorisi_id`, `kod`, `bolum`, `faaliyet`, `tehlike`, `risk`, `mevcut_onlem`, `oneri`, `mevzuat`, `olasilik`, `frekans`, `siddet`, `son_olasilik`, `son_frekans`, `son_siddet`, `sorumlu`, `termin`, `matris`, `created_at`, `updated_at`)
SELECT (SELECT `id` FROM `tehlike_kategorileri` WHERE `anahtar` = 'ekipman_eksantrik_pres' LIMIT 1), 'EKP-006', 'Eksantrik Pres', 'Kalıp bağlama', 'Standart dışı kalıp bağlama pabuçları ve cıvatalar nedeniyle kalıbın kayması', 'Kök neden: Kalıp, farklı boy ve kalitede cıvatalar, yamuk pabuçlar ve araya konan rastgele takozlarla bağlanıyor; tork değeri bilinmiyor. Çalışma sırasında kalıp kayar veya parçalanır → parça fırlaması, kalıp düşmesi, ezilme.', 'Bağlama elemanları standart değil, tork kontrolü yapılmıyor.', 'Tabla T-kanalına uygun standart kalıp bağlama pabuçları ve kalite sınıfı belirli cıvatalar kullanılmalı; hasarlı/uzamış cıvatalar ayıklanmalı. Kalıp bağlama sonrası tork anahtarıyla sıkma ve kontrol listesiyle onay yapılmalı. Kalıplar taşıma noktaları belirlenmiş şekilde uygun kaldırma ekipmanıyla taşınmalı.', 'İş Ekipmanlarının Kullanımında Sağlık ve Güvenlik Şartları Yönetmeliği; TS EN ISO 16092-1', 3, 3, 15, 1, 3, 15, 'Kalıp Ayarcısı / Bakım Şefi', '1 ay', '{\"olasilik\":3,\"siddet\":4,\"son_olasilik\":1,\"son_siddet\":4}', NOW(), NOW() FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM `tehlikeler` WHERE `kod` = 'EKP-006');

INSERT INTO `tehlikeler` (`tehlike_kategorisi_id`, `kod`, `bolum`, `faaliyet`, `tehlike`, `risk`, `mevcut_onlem`, `oneri`, `mevzuat`, `olasilik`, `frekans`, `siddet`, `son_olasilik`, `son_frekans`, `son_siddet`, `sorumlu`, `termin`, `matris`, `created_at`, `updated_at`)
SELECT (SELECT `id` FROM `tehlike_kategorileri` WHERE `anahtar` = 'ekipman_eksantrik_pres' LIMIT 1), 'EKP-007', 'Eksantrik Pres', 'Pres operasyonu', 'Pnömatik kavrama-fren grubunda basınç emniyet şalteri arızası ve gecikmeli duruş', 'Kök neden: Kavrama-fren hava basıncı düştüğünde presi durduran basınç şalteri devre dışı/arızalı; emniyet valfi (çift gövdeli) izlenmiyor, fren balataları aşınmış. Koç geç duruyor veya istem dışı iniyor; ışık bariyeri mesafesi de geçersiz hâle geliyor → el ezilmesi.', 'Basınç şalteri ve fren durma süresi periyodik olarak kontrol edilmiyor.', 'Basınç emniyet şalteri çalışır hâle getirilmeli ve basınç düşüşünde presi durduracak şekilde bağlanmalı. Kavrama-fren kumandasında izlemeli çift gövdeli emniyet valfi kullanılmalı. Fren durma süresi periyodik ölçülmeli (durma süresi ölçer) ve ışık bariyeri mesafesi bu değere göre doğrulanmalı; balatalar üretici talimatına göre yenilenmeli. Pres, yetkili kişilerce periyodik kontrole tabi tutulmalı.', 'İş Ekipmanlarının Kullanımında Sağlık ve Güvenlik Şartları Yönetmeliği (periyodik kontroller, kumanda sistemleri); TS EN ISO 16092-2; TS EN ISO 13849-1; TS EN ISO 13855', 3, 6, 40, 0.2, 6, 40, 'Bakım Şefi', '1 ay — periyodik ölçüm', '{\"olasilik\":3,\"siddet\":5,\"son_olasilik\":1,\"son_siddet\":5}', NOW(), NOW() FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM `tehlikeler` WHERE `kod` = 'EKP-007');

INSERT INTO `tehlikeler` (`tehlike_kategorisi_id`, `kod`, `bolum`, `faaliyet`, `tehlike`, `risk`, `mevcut_onlem`, `oneri`, `mevzuat`, `olasilik`, `frekans`, `siddet`, `son_olasilik`, `son_frekans`, `son_siddet`, `sorumlu`, `termin`, `matris`, `created_at`, `updated_at`)
SELECT (SELECT `id` FROM `tehlike_kategorileri` WHERE `anahtar` = 'ekipman_eksantrik_pres' LIMIT 1), 'EKP-008', 'Eksantrik Pres', 'Elle parça besleme', 'Ayak pedalı ile çalışmada ve elle parça beslemede koruyucusuz çalışma', 'Kök neden: Pres ayak pedalıyla çalıştırılıyor; parça kalıba elle konup alınıyor ve kalıp bölgesinde koruyucu/ışık perdesi yok. Pedala istem dışı basma veya el kalıptayken çevrimin başlaması → parmak/el kopması.', 'Pedal muhafazasız, kalıp bölgesi açık.', 'Elle beslemede kalıp bölgesi ışık bariyeri veya kapalı (ayarlanabilir) koruyucuyla korunmalı; ayak pedalı yalnız bu koruma varken kullanılmalı ve istem dışı basmayı önleyen kapaklı (muhafazalı) tip olmalı. Mümkünse çift el kumandasına geçilmeli. El kalıp içine girmeden besleme için itici, maşa veya vakumlu tutucu gibi el aletleri kullanılmalı; operatörler bu yöntemle eğitilmeli.', 'İş Ekipmanlarının Kullanımında Sağlık ve Güvenlik Şartları Yönetmeliği; Makine Emniyeti Yönetmeliği (2006/42/AT) Ek-I; TS EN ISO 16092-1; TS EN ISO 16092-2; TS EN ISO 13855', 6, 6, 40, 0.2, 6, 40, 'Üretim Sorumlusu / Operatör', 'Derhal', '{\"olasilik\":4,\"siddet\":5,\"son_olasilik\":1,\"son_siddet\":5}', NOW(), NOW() FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM `tehlikeler` WHERE `kod` = 'EKP-008');

INSERT INTO `tehlike_kategorileri` (`ad`, `anahtar`, `yontem`, `sira`, `created_at`, `updated_at`)
SELECT 'Ekipman – Hidrolik pres (üretim)', 'ekipman_hidrolik_pres', NULL, 500, NOW(), NOW() FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM `tehlike_kategorileri` WHERE `anahtar` = 'ekipman_hidrolik_pres');

INSERT INTO `tehlikeler` (`tehlike_kategorisi_id`, `kod`, `bolum`, `faaliyet`, `tehlike`, `risk`, `mevcut_onlem`, `oneri`, `mevzuat`, `olasilik`, `frekans`, `siddet`, `son_olasilik`, `son_frekans`, `son_siddet`, `sorumlu`, `termin`, `matris`, `created_at`, `updated_at`)
SELECT (SELECT `id` FROM `tehlike_kategorileri` WHERE `anahtar` = 'ekipman_hidrolik_pres' LIMIT 1), 'HDP-001', 'Hidrolik Pres', 'Pres operasyonu / bakım', 'Yüksek basınçlı hidrolik hortum patlaması ve sıcak yağ enjeksiyonu', 'Kök neden: Hortumlar ömrünü doldurmuş, sürtünme noktalarında aşınmış ve koruma kılıfı yok; kaçak kontrolü elle yapılıyor. Patlayan hortumdan çıkan yüksek basınçlı sıcak yağ cilde enjekte olabilir, göze gelebilir veya hortum kırbaç gibi savrulabilir → enjeksiyon yaralanması, yanık, göz yaralanması.', 'Hortumlar gözle kontrol ediliyor; değişim periyodu ve koruma kılıfı yok.', 'Operatör tarafına bakan hortumlara patlama koruma kılıfı (hortum çorabı) takılmalı, sürtünme noktaları spiral koruyucuyla korunmalı, savrulma riskine karşı hortum emniyet kelepçesi/zinciri kullanılmalı. Hortumlar üretim tarihine ve üretici ömrüne göre değiştirilmeli, değişim kaydı tutulmalı. Kaçak arama asla elle yapılmamalı (karton/kâğıt ile yapılmalı); bakım öncesi sistem basıncı boşaltılmalı. Yüz siperi ve uygun eldiven kullanılmalı.', 'İş Ekipmanlarının Kullanımında Sağlık ve Güvenlik Şartları Yönetmeliği; Makine Emniyeti Yönetmeliği (2006/42/AT) Ek-I; TS EN ISO 16092-1; TS EN ISO 16092-3; TS EN ISO 4413 (hidrolik sistemler)', 3, 6, 15, 0.5, 6, 15, 'Bakım Şefi', '1 ay — periyodik değişim', '{\"olasilik\":3,\"siddet\":4,\"son_olasilik\":1,\"son_siddet\":4}', NOW(), NOW() FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM `tehlikeler` WHERE `kod` = 'HDP-001');

INSERT INTO `tehlikeler` (`tehlike_kategorisi_id`, `kod`, `bolum`, `faaliyet`, `tehlike`, `risk`, `mevcut_onlem`, `oneri`, `mevzuat`, `olasilik`, `frekans`, `siddet`, `son_olasilik`, `son_frekans`, `son_siddet`, `sorumlu`, `termin`, `matris`, `created_at`, `updated_at`)
SELECT (SELECT `id` FROM `tehlike_kategorileri` WHERE `anahtar` = 'ekipman_hidrolik_pres' LIMIT 1), 'HDP-002', 'Hidrolik Pres', 'Pres operasyonu', 'Valf iç kaçağı nedeniyle üst koçun yerçekimiyle kontrolsüz kayması (inmesi)', 'Kök neden: Yön/tutma valflerinde iç kaçak var; koç durdurulduğunda yerinde kalmıyor, yavaşça veya aniden aşağı kayıyor. Operatör veya ayarcı kalıp bölgesine elini koyduğunda koç kendiliğinden iner → ezilme, uzuv kaybı.', 'Koç tutma valfi periyodik test edilmiyor; koç kayması gözlemleniyor ancak kayıt yok.', 'Koç, yerçekimiyle inmeye karşı izlemeli (konumu denetlenen) tutma/emniyet valfleriyle donatılmalı; iç kaçak yapan valfler değiştirilmeli. Koç kayma testi (durdurulmuş koçun belirli sürede kayma miktarı) periyodik yapılıp kaydedilmeli. Kalıp bölgesine girilen tüm işlerde koç mekanik emniyet takozuyla desteklenmeli. Pres, yetkili kişilerce periyodik kontrolden geçirilmeli.', 'İş Ekipmanlarının Kullanımında Sağlık ve Güvenlik Şartları Yönetmeliği; Makine Emniyeti Yönetmeliği (2006/42/AT) Ek-I; TS EN ISO 16092-1; TS EN ISO 16092-3; TS EN ISO 13849-1', 3, 6, 40, 0.2, 6, 40, 'Bakım Şefi', '1 ay', '{\"olasilik\":3,\"siddet\":5,\"son_olasilik\":1,\"son_siddet\":5}', NOW(), NOW() FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM `tehlikeler` WHERE `kod` = 'HDP-002');

INSERT INTO `tehlikeler` (`tehlike_kategorisi_id`, `kod`, `bolum`, `faaliyet`, `tehlike`, `risk`, `mevcut_onlem`, `oneri`, `mevzuat`, `olasilik`, `frekans`, `siddet`, `son_olasilik`, `son_frekans`, `son_siddet`, `sorumlu`, `termin`, `matris`, `created_at`, `updated_at`)
SELECT (SELECT `id` FROM `tehlike_kategorileri` WHERE `anahtar` = 'ekipman_hidrolik_pres' LIMIT 1), 'HDP-003', 'Hidrolik Pres', 'Kalıp değişimi / ayar', 'Kalıp değişimi sırasında elektriksel kilitli (interlock) emniyet takozu bulunmaması', 'Kök neden: Kalıp değişiminde koç yalnız hidrolik basınçla tutuluyor; mekanik emniyet takozu yok veya takoz takılıyken presin çalışmasını engelleyen kilitleme bulunmuyor. Hidrolik arıza ya da yanlışlıkla çalıştırmada koç düşer → ezilme, ölüm.', 'Emniyet takozu yok / kilitlemesiz takoz kullanılıyor.', 'Koç ağırlığını ve pres kuvvetini taşıyacak kapasitede emniyet takozu temin edilmeli; takoz yuvasından alındığında pres kumandasını kesen elektrik kilitlemeli emniyet svici (EN ISO 14119) bağlanmalı. Kalıp değişimi talimatına takoz kullanımı ve LOTO adımları eklenmeli, kalıp ayarcıları eğitilmeli.', 'İş Ekipmanlarının Kullanımında Sağlık ve Güvenlik Şartları Yönetmeliği; Makine Emniyeti Yönetmeliği (2006/42/AT) Ek-I; TS EN ISO 16092-1; TS EN ISO 16092-3; TS EN ISO 14119', 3, 3, 40, 0.2, 3, 40, 'Bakım Şefi / Kalıp Ayarcısı', '1 ay', '{\"olasilik\":3,\"siddet\":5,\"son_olasilik\":1,\"son_siddet\":5}', NOW(), NOW() FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM `tehlikeler` WHERE `kod` = 'HDP-003');

INSERT INTO `tehlikeler` (`tehlike_kategorisi_id`, `kod`, `bolum`, `faaliyet`, `tehlike`, `risk`, `mevcut_onlem`, `oneri`, `mevzuat`, `olasilik`, `frekans`, `siddet`, `son_olasilik`, `son_frekans`, `son_siddet`, `sorumlu`, `termin`, `matris`, `created_at`, `updated_at`)
SELECT (SELECT `id` FROM `tehlike_kategorileri` WHERE `anahtar` = 'ekipman_hidrolik_pres' LIMIT 1), 'HDP-004', 'Hidrolik Pres', 'Pres operasyonu', 'Arka ve yan bölgelerde sabit veya kilitli fiziki muhafaza bulunmaması', 'Kök neden: Koruma yalnız ön tarafta (ışık bariyeri / çift el) var; arka ve yanlardan kalıp bölgesine erişim açık. Arka taraftan parça alan veya müdahale eden çalışan koç hareketinde kalıp bölgesine uzanabilir → ezilme.', 'Ön tarafta ışık bariyeri var; arka ve yanlar açık.', 'Arka ve yan erişim noktaları EN ISO 14120’ye uygun sabit (alet olmadan sökülemeyen) koruyucularla kapatılmalı; sık erişim gereken yerlerde kapı kullanılacaksa EN ISO 14119’a uygun kilitleme (interlock) ile kapı açıkken pres çalışmamalı. Koruyucu mesafeleri EN ISO 13857 (uzanma mesafeleri) ve EN ISO 13855’e göre kontrol edilmeli.', 'İş Ekipmanlarının Kullanımında Sağlık ve Güvenlik Şartları Yönetmeliği; Makine Emniyeti Yönetmeliği (2006/42/AT) Ek-I; TS EN ISO 16092-1; TS EN ISO 16092-3; TS EN ISO 14120; TS EN ISO 14119; TS EN ISO 13857', 3, 6, 40, 0.2, 6, 40, 'Bakım Şefi / Üretim Sorumlusu', '1 ay', '{\"olasilik\":3,\"siddet\":5,\"son_olasilik\":1,\"son_siddet\":5}', NOW(), NOW() FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM `tehlikeler` WHERE `kod` = 'HDP-004');

INSERT INTO `tehlikeler` (`tehlike_kategorisi_id`, `kod`, `bolum`, `faaliyet`, `tehlike`, `risk`, `mevcut_onlem`, `oneri`, `mevzuat`, `olasilik`, `frekans`, `siddet`, `son_olasilik`, `son_frekans`, `son_siddet`, `sorumlu`, `termin`, `matris`, `created_at`, `updated_at`)
SELECT (SELECT `id` FROM `tehlike_kategorileri` WHERE `anahtar` = 'ekipman_hidrolik_pres' LIMIT 1), 'HDP-005', 'Hidrolik Pres', 'Pres operasyonu / bakım', 'Hidrolik yağ tankı sıcaklık / seviye uyarı sistemlerinin arızası ve yangın riski', 'Kök neden: Yağ sıcaklık ve seviye sensörleri devre dışı veya arızalı; soğutucu bakımsız. Aşırı ısınan yağ buharlaşır, kaçak yağ sıcak yüzeylere veya elektrik bileşenlerine temas eder → yangın, yanık, pompa hasarı ve ani basınç kaybıyla koç hareketi.', 'Sıcaklık göstergesi var ancak alarm/otomatik durdurma çalışmıyor; tank çevresinde yağ birikintisi var.', 'Yağ sıcaklığı ve seviye sensörleri alarm ve gerektiğinde otomatik durdurma verecek şekilde çalışır hâle getirilmeli; soğutucu ve filtreler bakım planına alınmalı. Kaçaklar giderilip tank çevresi temiz tutulmalı, yanıcı malzeme uzaklaştırılmalı. Pres yakınında uygun sınıfta yangın söndürücü bulundurulmalı; mümkünse yanmaya dayanıklı hidrolik yağ değerlendirilmeli.', 'İş Ekipmanlarının Kullanımında Sağlık ve Güvenlik Şartları Yönetmeliği; Makine Emniyeti Yönetmeliği (2006/42/AT) Ek-I; TS EN ISO 16092-1; TS EN ISO 16092-3; TS EN ISO 4413; Binaların Yangından Korunması Hakkında Yönetmelik', 1, 6, 40, 0.2, 6, 40, 'Bakım Şefi', '1 ay', '{\"olasilik\":2,\"siddet\":5,\"son_olasilik\":1,\"son_siddet\":5}', NOW(), NOW() FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM `tehlikeler` WHERE `kod` = 'HDP-005');

INSERT INTO `tehlike_kategorileri` (`ad`, `anahtar`, `yontem`, `sira`, `created_at`, `updated_at`)
SELECT 'Ekipman – Abkant pres (sac büküm)', 'ekipman_abkant_pres', NULL, 500, NOW(), NOW() FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM `tehlike_kategorileri` WHERE `anahtar` = 'ekipman_abkant_pres');

INSERT INTO `tehlikeler` (`tehlike_kategorisi_id`, `kod`, `bolum`, `faaliyet`, `tehlike`, `risk`, `mevcut_onlem`, `oneri`, `mevzuat`, `olasilik`, `frekans`, `siddet`, `son_olasilik`, `son_frekans`, `son_siddet`, `sorumlu`, `termin`, `matris`, `created_at`, `updated_at`)
SELECT (SELECT `id` FROM `tehlike_kategorileri` WHERE `anahtar` = 'ekipman_abkant_pres' LIMIT 1), 'ABK-001', 'Abkant Pres', 'Sac büküm operasyonu', 'Lazer parmak koruma sisteminin (DSP / Akas / Lazersafe vb.) muting veya hizalama hatası ya da kapatılması', 'Kök neden: Küçük ve çok kenarlı parçalarda lazer koruma \"işi yavaşlatıyor\" diye kapatılıyor veya bypass ediliyor; kalıp değişiminden sonra verici-alıcı hizası ayarlanmıyor, muting noktası yanlış. Operatör parmakları üst bıçak ile alt kalıp arasında kalır → parmak/el ezilmesi, kopması.', 'Lazer koruma mevcut; hizalama ve günlük test yapılmıyor, devre dışı bırakma anahtarı serbest erişimli.', 'Lazer koruma sistemi kapatılamayacak şekilde (anahtar yetkili kişide) korunmalı; her kalıp değişiminden sonra hizalama ve vardiya başı test parçasıyla fonksiyon testi yapılıp forma işlenmeli. Muting (korumanın susturulması) yalnız EN 12622’nin izin verdiği küçük kalıp açıklığına inildikten sonra devreye girmeli ve bu aşamada kapanma hızı standardın sınırını aşmamalı. Koruma kullanılamayan özel bükümlerde düşük hız ve çift el kumandası gibi standartta tanımlı alternatif yöntemler uygulanmalı.', 'İş Ekipmanlarının Kullanımında Sağlık ve Güvenlik Şartları Yönetmeliği; Makine Emniyeti Yönetmeliği (2006/42/AT) Ek-I; TS EN 12622 (hidrolik abkant presler); TS EN ISO 13855; TS EN 61496', 6, 6, 40, 0.2, 6, 40, 'Üretim Sorumlusu / Bakım Şefi', 'Derhal — vardiya başı test sürekli', '{\"olasilik\":4,\"siddet\":5,\"son_olasilik\":1,\"son_siddet\":5}', NOW(), NOW() FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM `tehlikeler` WHERE `kod` = 'ABK-001');

INSERT INTO `tehlikeler` (`tehlike_kategorisi_id`, `kod`, `bolum`, `faaliyet`, `tehlike`, `risk`, `mevcut_onlem`, `oneri`, `mevzuat`, `olasilik`, `frekans`, `siddet`, `son_olasilik`, `son_frekans`, `son_siddet`, `sorumlu`, `termin`, `matris`, `created_at`, `updated_at`)
SELECT (SELECT `id` FROM `tehlike_kategorileri` WHERE `anahtar` = 'ekipman_abkant_pres' LIMIT 1), 'ABK-002', 'Abkant Pres', 'Sac büküm operasyonu', 'Büküm sırasında sacın hızla yukarı fırlaması (whip-up) ve operatöre çarpması', 'Kök neden: Büyük ve ağır saclar büküm sırasında operatör tarafına doğru hızla kalkıyor; sac elle destekleniyor ve operatör savrulma alanında duruyor. Sac kenarı yüze, göğse veya kollara çarpar; elle tutulan sac eli kalıba doğru çekebilir → kesik, çarpma, ezilme.', 'Büyük saclar iki çalışan tarafından elle tutularak büküluyor; destek kolu yok.', 'Büyük saclar için sac takip eden büküm destek kolları (ön destek / bükme takipçisi) kullanılmalı. Operatörlerin sacın savrulma yayının dışında durması talimatla belirlenmeli ve işaretlenmeli. Ağır saclar kaldırma yardımcı ekipmanıyla beslenmeli; kesilmeye dirençli eldiven ve uygun iş kıyafeti kullanılmalı.', 'İş Ekipmanlarının Kullanımında Sağlık ve Güvenlik Şartları Yönetmeliği; Makine Emniyeti Yönetmeliği (2006/42/AT) Ek-I; TS EN 12622 (hidrolik abkant presler)', 3, 6, 15, 0.5, 6, 15, 'Üretim Sorumlusu / Operatör', '1 ay', '{\"olasilik\":3,\"siddet\":4,\"son_olasilik\":1,\"son_siddet\":4}', NOW(), NOW() FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM `tehlikeler` WHERE `kod` = 'ABK-002');

INSERT INTO `tehlikeler` (`tehlike_kategorisi_id`, `kod`, `bolum`, `faaliyet`, `tehlike`, `risk`, `mevcut_onlem`, `oneri`, `mevzuat`, `olasilik`, `frekans`, `siddet`, `son_olasilik`, `son_frekans`, `son_siddet`, `sorumlu`, `termin`, `matris`, `created_at`, `updated_at`)
SELECT (SELECT `id` FROM `tehlike_kategorileri` WHERE `anahtar` = 'ekipman_abkant_pres' LIMIT 1), 'ABK-003', 'Abkant Pres', 'Bıçak / kalıp değişimi', 'Bıçak ve kalıp değişiminde ayak pedalı kilidinin olmaması ve LOTO eksikliği', 'Kök neden: Bıçak ve alt kalıp değiştirilirken makine yalnız beklemeye alınıyor; ayak pedalı yerde ve kilitsiz, ana şalter kilitlenmiyor. Pedala istem dışı basılması veya başka bir çalışanın makineyi çalıştırması → el ve kol ezilmesi.', 'Yazılı LOTO talimatı ve pedal kilidi yok.', 'Abkanta özel yazılı LOTO talimatı hazırlanmalı: koçu alt konuma indir veya emniyetle destekle → ana şalteri kapatıp kişisel asma kilitle kilitle → etiket as → hidrolik basıncı boşalt → çalıştırmayı deneyerek enerjisizliği doğrula. Ayak pedalı kapaklı (muhafazalı) olmalı ve kalıp değişiminde devre dışı bırakılmalı (anahtarlı mod seçici). Talimat makineye asılmalı ve eğitim kaydı tutulmalı.', 'İş Ekipmanlarının Kullanımında Sağlık ve Güvenlik Şartları Yönetmeliği; Makine Emniyeti Yönetmeliği (2006/42/AT) Ek-I; TS EN 12622 (hidrolik abkant presler); Güvenlik ve Sağlık İşaretleri Yönetmeliği', 3, 3, 40, 0.5, 3, 40, 'Bakım Şefi / İSG Uzmanı', '1 hafta — sürekli uygulama', '{\"olasilik\":3,\"siddet\":5,\"son_olasilik\":1,\"son_siddet\":5}', NOW(), NOW() FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM `tehlikeler` WHERE `kod` = 'ABK-003');

INSERT INTO `tehlikeler` (`tehlike_kategorisi_id`, `kod`, `bolum`, `faaliyet`, `tehlike`, `risk`, `mevcut_onlem`, `oneri`, `mevzuat`, `olasilik`, `frekans`, `siddet`, `son_olasilik`, `son_frekans`, `son_siddet`, `sorumlu`, `termin`, `matris`, `created_at`, `updated_at`)
SELECT (SELECT `id` FROM `tehlike_kategorileri` WHERE `anahtar` = 'ekipman_abkant_pres' LIMIT 1), 'ABK-004', 'Abkant Pres', 'Sac büküm operasyonu / ayar', 'Arka dayama (backgauge) eksenlerinin hızlı hareketinde sıkışma riski', 'Kök neden: Arka dayama eksenleri programla hızlı konumlanıyor; makinenin arkasına geçen çalışan veya parçayı arkadan alan operatör dayama ile gövde arasında sıkışabiliyor. Arka bölge açık ve uyarı yok → el, kol veya gövde sıkışması.', 'Makinenin arkası açık; arka bölgeye giriş kısıtlanmamış.', 'Makinenin arka bölgesi EN ISO 14120’ye uygun sabit koruyucularla veya kilitli kapı / ışık perdesi ile korunmalı; arka bölgeye girişte dayama hareketi durmalı. Ayar ve parça alma işleri ön taraftan yapılacak şekilde düzenlenmeli; arka bölge zemin işaretlemesi ve uyarı levhasıyla belirtilmeli.', 'İş Ekipmanlarının Kullanımında Sağlık ve Güvenlik Şartları Yönetmeliği; Makine Emniyeti Yönetmeliği (2006/42/AT) Ek-I; TS EN 12622 (hidrolik abkant presler); TS EN ISO 14120; TS EN ISO 14119', 3, 6, 7, 1, 6, 7, 'Bakım Şefi', '1 ay', '{\"olasilik\":3,\"siddet\":3,\"son_olasilik\":1,\"son_siddet\":3}', NOW(), NOW() FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM `tehlikeler` WHERE `kod` = 'ABK-004');

INSERT INTO `tehlikeler` (`tehlike_kategorisi_id`, `kod`, `bolum`, `faaliyet`, `tehlike`, `risk`, `mevcut_onlem`, `oneri`, `mevzuat`, `olasilik`, `frekans`, `siddet`, `son_olasilik`, `son_frekans`, `son_siddet`, `sorumlu`, `termin`, `matris`, `created_at`, `updated_at`)
SELECT (SELECT `id` FROM `tehlike_kategorileri` WHERE `anahtar` = 'ekipman_abkant_pres' LIMIT 1), 'ABK-005', 'Abkant Pres', 'Kalıp seçimi / sac büküm', 'Yanlış V kanal seçimi nedeniyle aşırı tonajda kalıp kırılması ve parça fırlaması', 'Kök neden: Sac kalınlığına göre çok dar V kanal seçiliyor veya tonaj tablosuna bakılmıyor; kalıp ve bıçak kapasitesinin üstünde yükleniyor. Kalıp çatlar veya kırılır, parça ya da kalıp parçası fırlar → çarpma, göz ve yüz yaralanması; makine hasarı.', 'Tonaj tablosu makinede yok; V kanal seçimi operatörün tecrübesine bırakılmış.', 'Her makineye kalıp üreticisinin tonaj (kuvvet) tablosu asılmalı; V kanal açıklığı sac kalınlığı ve malzemesine göre tablodan seçilmeli, kalıp ve bıçak üzerinde yazan azami yük aşılmamalı. Makine kuvvet sınırlaması doğru ayarlanmalı; çatlak veya hasarlı kalıplar kullanımdan kaldırılmalı. Operatörlere kalıp seçimi eğitimi verilmeli, koruyucu gözlük kullanılmalı.', 'İş Ekipmanlarının Kullanımında Sağlık ve Güvenlik Şartları Yönetmeliği; Makine Emniyeti Yönetmeliği (2006/42/AT) Ek-I; TS EN 12622 (hidrolik abkant presler)', 3, 3, 15, 0.5, 3, 15, 'Kalıp Ayarcısı / Operatör', '1 ay', '{\"olasilik\":3,\"siddet\":4,\"son_olasilik\":1,\"son_siddet\":4}', NOW(), NOW() FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM `tehlikeler` WHERE `kod` = 'ABK-005');

-- DOĞRULAMA (beklenen: ekipman_abkant_pres 5, ekipman_eksantrik_pres 8, ekipman_hidrolik_pres 5)
SELECT k.`anahtar`, COUNT(t.`id`) AS madde FROM `tehlike_kategorileri` k LEFT JOIN `tehlikeler` t ON t.`tehlike_kategorisi_id` = k.`id`
WHERE k.`anahtar` IN ('ekipman_eksantrik_pres', 'ekipman_hidrolik_pres', 'ekipman_abkant_pres') GROUP BY k.`anahtar`;
